const SUPPORTED_ANALYTICS_EVENT_TYPES = [
  "survey_answer",
  "app_installed",
  "app_foreground",
  "app_background",
  "screen_view",
  "link_click",
  "in_app_message_impression",
  "in_app_message_click",
  "in_app_message_close",
  "in_app_message_submit"
];

/**
 * Convert a Meiro Mobile SDK request into Pipes analytics events.
 *
 * FCM report envelopes are not analytics events. The static Channels endpoint handles
 * them. This collection endpoint accepts and discards such envelopes.
 *
 * @param {object} options
 * @param {unknown} options.payload - Parsed Mobile SDK POST JSON body
 * @param {Record<string, string>} options.headers - Incoming request headers
 * @param {Record<string, string>} options.secrets - Source-bound Pipes secrets
 * @returns {object[]} Supported analytics events, empty when the request carries none
 */
function transform_request({ payload, headers, secrets }) {
  return read_sdk_events(payload)
    .filter(is_supported_sdk_event)
    .map(map_sdk_event);
}

function read_sdk_events(payload) {
  if (Array.isArray(payload)) return payload;
  if (is_plain_object(payload)) return [payload];

  throw new Error(
    "Mobile SDK collection expects a top-level JSON object or an array of SDK events."
  );
}

function is_supported_sdk_event(sdkEvent) {
  if (!is_plain_object(sdkEvent)) return false;
  if (sdkEvent.event_type === "event_custom") {
    return get_custom_event_type(sdkEvent) !== null;
  }
  return SUPPORTED_ANALYTICS_EVENT_TYPES.includes(sdkEvent.event_type);
}

function map_sdk_event(sdkEvent) {
  return {
    event_type: resolve_event_type(sdkEvent),
    event_time: normalize_event_time(sdkEvent.event_timestamp),
    event_payload: sdkEvent.event_type === "survey_answer" ? {
      ...sdkEvent,
      survey_id: sdkEvent.event_data?.survey_id,
      survey_name: sdkEvent.event_data?.survey_name,
      survey_version: sdkEvent.event_data?.survey_version,
      response_id: sdkEvent.event_data?.response_id,
      submitted_at: sdkEvent.event_data?.submitted_at,
      answers: sdkEvent.event_data?.answers,
      delivery_surface: sdkEvent.event_data?.delivery_surface,
      message_id: sdkEvent.event_data?.message_id,
      message_version: sdkEvent.event_data?.message_version,
      display_id: sdkEvent.event_data?.display_id
    } : { ...sdkEvent },
    ...(sdkEvent.event_type === "survey_answer" ? {event_key: sdkEvent.event_data?.response_id} : {}),
    ...(sdkEvent.event_type.startsWith("in_app_message_") && sdkEvent.event_type !== "event_custom"
      ? { event_key: sdkEvent.event_data?.occurrence_id } : {})
  };
}

function resolve_event_type(sdkEvent) {
  return sdkEvent.event_type === "event_custom"
    ? get_custom_event_type(sdkEvent)
    : sdkEvent.event_type;
}

function get_custom_event_type(sdkEvent) {
  const name = sdkEvent.event_data?.name;
  if (typeof name !== "string") return null;
  return /^[A-Za-z0-9](?:[A-Za-z0-9_-]*[A-Za-z0-9])?$/.test(name)
    ? name
    : null;
}

/**
 * Accept ISO 8601, epoch seconds, and epoch milliseconds. An unparseable value is returned
 * unchanged so Pipes reports it as an invalid event_time instead of silently dropping it.
 */
function normalize_event_time(value) {
  if (typeof value !== "string") return "";

  const trimmed = value.trim();
  if (/^\d{10}$/.test(trimmed)) {
    return new Date(Number(trimmed) * 1000).toISOString();
  }
  if (/^\d{13}$/.test(trimmed)) {
    return new Date(Number(trimmed)).toISOString();
  }

  const parsed = new Date(trimmed);
  if (Number.isNaN(parsed.getTime())) return value;
  return parsed.toISOString();
}

function is_plain_object(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
